function evidence = f90_xaero03_extract_evidence(modelPath,outDir)
%F90_XAERO03_EXTRACT_EVIDENCE Dedicated multi-scenario evidence extractor.
arguments
    modelPath (1,1) string = ...
        fullfile(getenv("SIMUVERITY_TASK_ROOT"), "reference", "files", "XAERO03_reference.slx")
    outDir (1,1) string = ...
        tempdir
end

repoRoot = fullfile(getenv("SIMUVERITY_TASK_VENDOR_ROOT"));
taskCode = fileparts(mfilename("fullpath"));
if ~isfolder(outDir), mkdir(outDir); end
addpath(taskCode,"-begin");
addpath(fullfile(repoRoot,"scripts","xp9"),"-end");
def = f90_xaero03_definition;
receipt = empty_receipt(def,modelPath);

inputNames = string({def.public_inputs.name});
baseSnapshot = snapshot_base(inputNames);
baseCleanup = onCleanup(@() restore_base(baseSnapshot)); %#ok<NASGU>

try
    assert(isfile(modelPath),"F90_XAERO03_MODEL_NOT_FOUND");
    receipt.model_file_presence = xp9_file_presence_file(modelPath);
    nominal = nominal_values(def);
    set_base(nominal);
    [~,model] = fileparts(modelPath);
    model = string(model);
    if bdIsLoaded(model), close_system(model,0); end
    load_system(modelPath);
    modelCleanup = onCleanup(@() close_model(model)); %#ok<NASGU>
    receipt.load_pass = true;
    receipt.static_audit = static_audit(model,def);

    set_param(model,"SimulationCommand","update");
    receipt.update_pass = true;
    feval(model,[],[],[],"compile");
    feval(model,[],[],[],"term");
    receipt.compile_pass = true;

    scenarioDefs = [ ...
        struct("id","nominal","values",nominal),def.scenarios];
    runs = repmat(empty_run,1,numel(scenarioDefs));
    rows = repmat(empty_row,1,numel(scenarioDefs));
    for index = 1:numel(scenarioDefs)
        runs(index) = run_scenario(model,scenarioDefs(index),def);
        rows(index) = measure_run(runs(index),def);
    end
    receipt.scenario_rows = rows;
    suite = measure_suite(rows);
    pairs = measure_pairs(rows,runs,def);
    receipt.metric_values = struct( ...
        "physical_suite",suite,"causal_pairs",pairs);

    % Save the complete simulation-derived artifact before the trusted
    % central flow creates its immutable evidence lock.
    timeseriesPath = fullfile(outDir,"evidence_timeseries.mat");
    save(timeseriesPath,"runs","-v7.3");
    timeseriesArtifact = struct( ...
        "path",string(timeseriesPath), ...
        "file_presence",xp9_file_presence_file(timeseriesPath), ...
        "format","MATLAB v7.3 MAT", ...
        "variable","runs", ...
        "contains", ...
            "scenario inputs, time, flight_state, air_data, actuation and force_moment");
catch extractionError
    receipt.valid = false;
    receipt.failure_reasons = unique([receipt.failure_reasons; ...
        "EVIDENCE_EXTRACTION_EXCEPTION:" + ...
        string(extractionError.identifier) + ...
        ":" + string(extractionError.message)],"stable");
    receipt.error_identifier = string(extractionError.identifier);
    receipt.error_message = string(extractionError.message);
end

receipt.finished_at = timestamp;
receipt.runtime_identity = runtime_identity;
if exist("runs","var") && exist("timeseriesArtifact","var")
    evidence = evidence_from_receipt( ...
        receipt,def,runs,timeseriesArtifact);
else
    evidence = evidence_from_receipt(receipt,def);
end
write_json(fullfile(outDir,"evidence.json"),evidence);
fprintf("F90_XAERO03_EVIDENCE extraction_only=1 out=%s\n",outDir);
end

function run = run_scenario(model,scenario,def)
run = empty_run;
run.id = string(scenario.id);
run.inputs = scenario.values;
try
    set_base(run.inputs);
    input = Simulink.SimulationInput(model);
    names = fieldnames(run.inputs);
    for index = 1:numel(names)
        input = input.setVariable(names{index}, ...
            run.inputs.(names{index}),"Workspace",model);
    end
    input = input.setModelParameter( ...
        "StopTime",num2str(def.sim.stop,17), ...
        "ReturnWorkspaceOutputs","on");
    output = sim(input);
    outputNames = string({def.outputs.name});
    data = cell(1,numel(outputNames));
    times = cell(1,numel(outputNames));
    for index = 1:numel(outputNames)
        value = simuverity_public_output_compatibility( ...
            output,outputNames(index),def.outputs(index).channels, ...
            AllowBaseWorkspace=true);
        times{index} = double(value.Time(:));
        data{index} = normalize_data( ...
            value,times{index},def.outputs(index).channels);
    end
    time = times{1};
    assert(numel(time) >= 100,"F90_XAERO03_TOO_FEW_SAMPLES");
    assert(abs(time(1)) < 1e-9 && ...
        time(end) >= def.sim.stop-1e-7, ...
        "F90_XAERO03_TIME_COVERAGE");
    assert(all(diff(time) > 0),"F90_XAERO03_TIME_NOT_INCREASING");
    for index = 2:numel(times)
        assert(numel(times{index}) == numel(time) && ...
            max(abs(times{index}-time)) < 1e-9, ...
            "F90_XAERO03_OUTPUT_TIME_MISMATCH");
    end
    allData = horzcat(data{:});
    assert(isreal(allData) && all(isfinite(allData),"all"), ...
        "F90_XAERO03_NONFINITE_OUTPUT");
    run.time = time;
    run.flight_state = data{1};
    run.air_data = data{2};
    run.actuation = data{3};
    run.force_moment = data{4};
    run.valid = true;
catch runError
    run.valid = false;
    run.error = string(runError.identifier) + ":" + ...
        string(runError.message);
end
end

function row = measure_run(run,def)
row = empty_row;
row.id = run.id;
if ~run.valid
    row.error = run.error;
    return
end
try
    t = run.time;
    state = run.flight_state;
    air = run.air_data;
    act = run.actuation;
    loads = run.force_moment;
    values = run.inputs;

    positionNed = [state(:,1:2),-state(:,3)];
    inertialVelocity = state(:,4:6);
    trueAirspeed = state(:,7);
    alpha = state(:,8);
    beta = state(:,9);
    euler = state(:,10:12);
    omega = state(:,13:15);
    density = air(:,1);
    dynamicPressure = air(:,2);
    mach = air(:,3);
    gustNed = air(:,4:6);
    command = act(:,1:5);
    actual = act(:,6:10);
    aerodynamicForce = loads(:,1:3);
    aerodynamicMoment = loads(:,4:6);
    totalForce = loads(:,7:9);
    totalMoment = loads(:,10:12);

    finalMask = t >= 24;
    activeGust = t >= double(values.gust_time) & ...
        t < double(values.gust_time)+ ...
        double(def.public_constants.gust_duration_s);
    beforeCommand = t >= .25 & ...
        t <= min(double(values.command_time)-.25,2.5);
    dynamicsMask = t >= .10 & t <= def.sim.stop-.10;

    expectedGust = expected_gust(t,values,def);
    row.samples = numel(t);
    row.final_altitude_rms_error_m = local_rms( ...
        state(finalMask,3)-double(values.altitude_reference));
    row.final_airspeed_rms_error_m_per_s = local_rms( ...
        trueAirspeed(finalMask)-double(values.airspeed_reference));
    row.final_heading_rms_error_rad = local_rms(wrap_angle( ...
        euler(finalMask,3)-double(values.heading_change)));
    row.final_sideslip_rms_rad = local_rms(beta(finalMask));
    row.final_body_rate_rms_rad_per_s = local_rms( ...
        vecnorm(omega(finalMask,:),2,2));
    row.final_heading_mean_rad = circular_mean(euler(finalMask,3));

    alphaLimits = double(def.public_constants.angle_of_attack_limits_rad);
    betaLimit = double(def.public_constants.sideslip_limit_rad);
    row.alpha_violation_fraction = mean( ...
        alpha < alphaLimits(1)-1e-6 | alpha > alphaLimits(2)+1e-6);
    row.beta_violation_fraction = mean(abs(beta) > betaLimit+1e-6);
    row.minimum_altitude_m = min(state(:,3));
    row.minimum_airspeed_m_per_s = min(trueAirspeed);
    row.maximum_abs_roll_rad = max(abs(euler(:,1)));
    row.maximum_abs_pitch_rad = max(abs(euler(:,2)));
    row.maximum_abs_body_rate_rad_per_s = max(abs(omega),[],"all");

    lower = [ ...
        def.public_constants.thrust_limits_N(1), ...
        -def.public_constants.elevator_limit_rad, ...
        -def.public_constants.aileron_limit_rad, ...
        -def.public_constants.rudder_limit_rad, ...
        def.public_constants.leading_edge_flap_limits_rad(1)];
    upper = [ ...
        def.public_constants.thrust_limits_N(2), ...
        def.public_constants.elevator_limit_rad, ...
        def.public_constants.aileron_limit_rad, ...
        def.public_constants.rudder_limit_rad, ...
        def.public_constants.leading_edge_flap_limits_rad(2)];
    ranges = upper-lower;
    positionViolation = max([ ...
        (lower-actual)./ranges,(actual-upper)./ranges, ...
        zeros(size(actual))],[],2);
    row.actuator_position_violation = max(positionViolation,[],"all");
    actualDerivative = time_derivative(actual,t);
    rateLimits = [ ...
        def.public_constants.thrust_rate_limit_N_per_s, ...
        def.public_constants.elevator_rate_limit_rad_per_s, ...
        def.public_constants.aileron_rate_limit_rad_per_s, ...
        def.public_constants.rudder_rate_limit_rad_per_s, ...
        def.public_constants.leading_edge_flap_rate_limit_rad_per_s];
    rateRatio = abs(actualDerivative)./rateLimits;
    row.actuator_rate_ratio_max = max(rateRatio,[],"all");
    row.actuator_rate_violation = max(row.actuator_rate_ratio_max-1,0);
    nearLimit = actual <= lower+.01*ranges | ...
        actual >= upper-.01*ranges;
    saturationByChannel = mean(nearLimit,1);
    [row.actuator_saturation_fraction,worstSaturationChannel] = ...
        max(saturationByChannel);
    row.actuator_saturation_fraction_by_channel = ...
        saturationByChannel;
    actuatorNames = [ ...
        "thrust","elevator","aileron","rudder","leading_edge_flap"];
    row.actuator_saturation_worst_channel = ...
        actuatorNames(worstSaturationChannel);
    normalizedLag = (command-actual)./ranges;
    row.actuator_lag_evidence = ...
        max(sqrt(mean(normalizedLag.^2,1)));
    responseCorrelations = zeros(1,5);
    activeActuators = false(1,5);
    for channel = 1:5
        responseCorrelations(channel) = positive_correlation( ...
            command(:,channel),actual(:,channel));
        activeActuators(channel) = ...
            std(command(:,channel)/ranges(channel)) > 1e-4 && ...
            std(actual(:,channel)/ranges(channel)) > 1e-4;
    end
    if nnz(activeActuators) >= 3
        row.actuator_response_correlation = ...
            min(responseCorrelations(activeActuators));
    else
        row.actuator_response_correlation = 0;
    end

    row.gust_schedule_error = local_rms(gustNed-expectedGust) / ...
        max(double(values.gust_speed),1);
    expectedDensity = 1.225*exp(-max(state(:,3),0)/8500);
    temperature = max(216.65,288.15-.0065*max(state(:,3),0));
    expectedSoundSpeed = sqrt(1.4*287.05*temperature);
    row.density_closure_error = local_rms( ...
        density-expectedDensity)/max(local_rms(density),.2);
    row.dynamic_pressure_closure_error = local_rms( ...
        dynamicPressure-.5*density.*trueAirspeed.^2) / ...
        max(local_rms(dynamicPressure),100);
    row.mach_closure_error = local_rms( ...
        mach-trueAirspeed./expectedSoundSpeed) / ...
        max(local_rms(mach),.1);

    dcm = rotation_series(euler);
    expectedRelative = zeros(size(inertialVelocity));
    bodyVelocity = zeros(size(inertialVelocity));
    gravityBody = zeros(size(inertialVelocity));
    mass = double(def.public_constants.mass_kg);
    gravity = double(def.public_constants.gravity_m_per_s2);
    for sample = 1:numel(t)
        expectedRelative(sample,:) = ...
            (dcm(:,:,sample)'*( ...
            inertialVelocity(sample,:)-gustNed(sample,:))')';
        bodyVelocity(sample,:) = ...
            (dcm(:,:,sample)'*inertialVelocity(sample,:)')';
        gravityBody(sample,:) = ...
            (dcm(:,:,sample)'*[0;0;mass*gravity])';
    end
    expectedSpeed = vecnorm(expectedRelative,2,2);
    expectedAlpha = atan2( ...
        expectedRelative(:,3),expectedRelative(:,1));
    expectedBeta = asin(clip( ...
        expectedRelative(:,2)./max(expectedSpeed,1),-.999,.999));
    row.relative_wind_closure_error = local_rms([ ...
        (trueAirspeed-expectedSpeed)./max(expectedSpeed,30), ...
        wrap_angle(alpha-expectedAlpha), ...
        wrap_angle(beta-expectedBeta)]);

    positionDerivative = time_derivative(positionNed,t);
    row.position_velocity_closure_error = local_rms( ...
        positionDerivative(dynamicsMask,:)- ...
        inertialVelocity(dynamicsMask,:)) / ...
        max(local_rms(inertialVelocity(dynamicsMask,:)),30);
    continuousEuler = euler;
    continuousEuler(:,3) = unwrap(continuousEuler(:,3));
    eulerDerivative = time_derivative(continuousEuler,t);
    expectedEulerDerivative = zeros(size(euler));
    for sample = 1:numel(t)
        phi = euler(sample,1);
        theta = euler(sample,2);
        cosineTheta = sign(cos(theta))*max(abs(cos(theta)),.15);
        if cosineTheta == 0, cosineTheta = .15; end
        transform = [ ...
            1 sin(phi)*tan(theta) cos(phi)*tan(theta); ...
            0 cos(phi) -sin(phi); ...
            0 sin(phi)/cosineTheta cos(phi)/cosineTheta];
        expectedEulerDerivative(sample,:) = ...
            (transform*omega(sample,:)')';
    end
    row.euler_rate_closure_error = local_rms( ...
        eulerDerivative(dynamicsMask,:)- ...
        expectedEulerDerivative(dynamicsMask,:)) / ...
        max(local_rms(expectedEulerDerivative(dynamicsMask,:)),.05);

    bodyDerivative = time_derivative(bodyVelocity,t);
    expectedForce = zeros(size(totalForce));
    for sample = 1:numel(t)
        expectedForce(sample,:) = mass*( ...
            bodyDerivative(sample,:)+ ...
            cross(omega(sample,:),bodyVelocity(sample,:)));
    end
    row.translational_balance_error = local_rms( ...
        totalForce(dynamicsMask,:)-expectedForce(dynamicsMask,:)) / ...
        max(local_rms(totalForce(dynamicsMask,:)),mass);

    omegaDerivative = time_derivative(omega,t);
    inertia = double(def.public_constants.inertia_kg_m2);
    expectedMoment = zeros(size(totalMoment));
    for sample = 1:numel(t)
        angularMomentum = inertia*omega(sample,:)';
        expectedMoment(sample,:) = ( ...
            inertia*omegaDerivative(sample,:)'+ ...
            cross(omega(sample,:)',angularMomentum))';
    end
    row.rotational_balance_error = local_rms( ...
        totalMoment(dynamicsMask,:)-expectedMoment(dynamicsMask,:)) / ...
        max(local_rms(totalMoment(dynamicsMask,:)),1000);

    expectedTotalForce = aerodynamicForce+ ...
        [actual(:,1),zeros(numel(t),2)]+gravityBody;
    row.force_path_error = local_rms( ...
        totalForce-expectedTotalForce) / ...
        max(local_rms(totalForce),mass);
    row.total_moment_path_error = local_rms( ...
        totalMoment-aerodynamicMoment) / ...
        max(local_rms(totalMoment),1000);

    controlSignatures = [ ...
        positive_correlation(actual(:,2),-aerodynamicMoment(:,2)), ...
        positive_correlation(actual(:,3),aerodynamicMoment(:,1)), ...
        positive_correlation(alpha,-aerodynamicForce(:,3))];
    row.control_signature = min(controlSignatures);
    row.pressure_load_correlation = positive_correlation( ...
        dynamicPressure.*max(abs(alpha),.02), ...
        abs(aerodynamicForce(:,3)));

    headingReference = zeros(size(t));
    headingReference(t >= double(values.command_time)) = ...
        double(values.heading_change);
    altitudeError = double(values.altitude_reference)-state(:,3);
    speedError = double(values.airspeed_reference)-trueAirspeed;
    headingError = wrap_angle(headingReference-euler(:,3));
    feedback = [ ...
        positive_correlation(altitudeError,-command(:,2)), ...
        positive_correlation(speedError,command(:,1)), ...
        positive_correlation(headingError,euler(:,1))];
    row.feedback_correlation = median(feedback);

    row.initial_release_rate_peak = ...
        max(vecnorm(omega(beforeCommand,:),2,2));
    row.initial_release_altitude_change_m = ...
        max(abs(state(beforeCommand,3)-state(1,3)));
    row.initial_release_speed_change_m_per_s = ...
        max(abs(trueAirspeed(beforeCommand)-trueAirspeed(1)));
    if any(activeGust)
        row.gust_window_qbar_change = ...
            max(dynamicPressure(activeGust))-min(dynamicPressure(activeGust));
        row.gust_window_load_rms = ...
            local_rms(aerodynamicForce(activeGust,:));
    else
        row.gust_window_qbar_change = 0;
        row.gust_window_load_rms = 0;
    end
    row.valid = broad_domain(row,t, ...
        state,air,act,loads,def);
    if ~row.valid, row.error = "BROAD_FLIGHT_DOMAIN_FAILED"; end
catch measureError
    row.valid = false;
    row.error = string(measureError.identifier) + ":" + ...
        string(measureError.message);
end
end

function valid = broad_domain(row,time,state,air,act,loads,def)
valid = row.samples >= 100 && ...
    abs(time(1)) < 1e-9 && time(end) >= def.sim.stop-1e-7 && ...
    min(state(:,3)) > 100 && max(state(:,3)) < 20000 && ...
    min(state(:,7)) > 20 && max(state(:,7)) < 400 && ...
    max(abs(state(:,8:9)),[],"all") < 1.5 && ...
    max(abs(state(:,10:11)),[],"all") < 1.55 && ...
    max(abs(state(:,13:15)),[],"all") < 8 && ...
    min(air(:,1)) > .05 && max(air(:,1)) < 2 && ...
    min(air(:,2)) >= 0 && max(air(:,2)) < 1e6 && ...
    min(air(:,3)) > .02 && max(air(:,3)) < 2 && ...
    max(abs(act),[],"all") < 2e5 && ...
    max(abs(loads(:,1:3)),[],"all") < 5e6 && ...
    max(abs(loads(:,4:12)),[],"all") < 5e7;
end

function suite = measure_suite(rows)
suite = empty_suite;
validRows = rows([rows.valid]);
if isempty(validRows), return; end
suite.position_velocity_worst = ...
    max([validRows.position_velocity_closure_error]);
suite.euler_rate_worst = ...
    max([validRows.euler_rate_closure_error]);
suite.relative_wind_worst = ...
    max([validRows.relative_wind_closure_error]);
suite.density_worst = ...
    max([validRows.density_closure_error]);
suite.dynamic_pressure_worst = ...
    max([validRows.dynamic_pressure_closure_error]);
suite.mach_worst = max([validRows.mach_closure_error]);
suite.gust_schedule_worst = ...
    max([validRows.gust_schedule_error]);
suite.translational_balance_worst = ...
    max([validRows.translational_balance_error]);
suite.rotational_balance_worst = ...
    max([validRows.rotational_balance_error]);
suite.force_path_worst = max([validRows.force_path_error]);
suite.total_moment_path_worst = ...
    max([validRows.total_moment_path_error]);
suite.actuator_position_violation_worst = ...
    max([validRows.actuator_position_violation]);
suite.actuator_rate_violation_worst = ...
    max([validRows.actuator_rate_violation]);
suite.actuator_rate_ratio_max = ...
    max([validRows.actuator_rate_ratio_max]);
[suite.actuator_saturation_worst,worstSaturationRow] = ...
    max([validRows.actuator_saturation_fraction]);
suite.actuator_saturation_worst_scenario = ...
    validRows(worstSaturationRow).id;
suite.actuator_saturation_worst_channel = ...
    validRows(worstSaturationRow).actuator_saturation_worst_channel;
suite.actuator_saturation_fraction_by_channel_worst = ...
    max(vertcat(validRows.actuator_saturation_fraction_by_channel),[],1);
suite.actuator_lag_evidence_max = ...
    max([validRows.actuator_lag_evidence]);
suite.actuator_response_correlation_min = ...
    min([validRows.actuator_response_correlation]);
suite.control_signature_min = ...
    min([validRows.control_signature]);
suite.pressure_load_correlation_min = ...
    min([validRows.pressure_load_correlation]);
suite.feedback_correlation_min = ...
    min([validRows.feedback_correlation]);
suite.alpha_violation_worst = ...
    max([validRows.alpha_violation_fraction]);
suite.beta_violation_worst = ...
    max([validRows.beta_violation_fraction]);
end

function pairs = measure_pairs(rows,runs,def)
pairs = empty_pairs;
left = row_by_id(rows,"heading_pair_left");
right = row_by_id(rows,"heading_pair_right");
if left.valid && right.valid
    pairs.heading = struct( ...
        "valid",true, ...
        "left_final_heading_rad",left.final_heading_mean_rad, ...
        "right_final_heading_rad",right.final_heading_mean_rad, ...
        "left_final_heading_rms_error_rad", ...
            left.final_heading_rms_error_rad, ...
        "right_final_heading_rms_error_rad", ...
            right.final_heading_rms_error_rad, ...
        "symmetry_error_rad", ...
            abs(abs(left.final_heading_mean_rad)- ...
            abs(right.final_heading_mean_rad)));
end

noGustRun = run_by_id(runs,"gust_pair_none");
gustRun = run_by_id(runs,"gust_pair_crosswind");
noGust = row_by_id(rows,"gust_pair_none");
gust = row_by_id(rows,"gust_pair_crosswind");
if noGust.valid && gust.valid && noGustRun.valid && gustRun.valid
    t = gustRun.time;
    active = t >= double(gustRun.inputs.gust_time) & ...
        t < double(gustRun.inputs.gust_time)+ ...
        double(def.public_constants.gust_duration_s);
    recovery = t >= double(gustRun.inputs.gust_time)+4 & t <= 24;
    stateScale = [200 200 100 20 20 20 20 .2 .2 .4 .4 .4 1 1 1];
    stateDelta = local_rms( ...
        (gustRun.flight_state(active,:)- ...
        noGustRun.flight_state(active,:))./stateScale);
    airScale = [1 20000 1];
    airDelta = local_rms( ...
        (gustRun.air_data(active,1:3)- ...
        noGustRun.air_data(active,1:3))./airScale);
    loadScale = [1e5 1e5 1e5 5e5 5e5 5e5 ...
        1e5 1e5 1e5 5e5 5e5 5e5];
    loadDelta = local_rms( ...
        (gustRun.force_moment(active,:)- ...
        noGustRun.force_moment(active,:))./loadScale);
    actuatorScale = [40000 .4 .35 .5 .4 40000 .4 .35 .5 .4];
    actuatorDelta = local_rms( ...
        (gustRun.actuation(active,:)- ...
        noGustRun.actuation(active,:))./actuatorScale);
    if any(recovery)
        recoveryState = [ ...
            (gustRun.flight_state(recovery,3)- ...
                noGustRun.flight_state(recovery,3))/100, ...
            (gustRun.flight_state(recovery,7)- ...
                noGustRun.flight_state(recovery,7))/20, ...
            wrap_angle(gustRun.flight_state(recovery,12)- ...
                noGustRun.flight_state(recovery,12))/.4, ...
            (gustRun.flight_state(recovery,9)- ...
                noGustRun.flight_state(recovery,9))/.2, ...
            gustRun.flight_state(recovery,13:15)- ...
                noGustRun.flight_state(recovery,13:15)];
        recoveryDelta = local_rms( ...
            recoveryState);
    else
        recoveryDelta = Inf;
    end
    pairs.gust = struct( ...
        "valid",true, ...
        "paired_scenario_ids", ...
            ["gust_pair_none","gust_pair_crosswind"], ...
        "gust_duration_s",double(def.public_constants.gust_duration_s), ...
        "recovery_start_s",double(gustRun.inputs.gust_time)+4, ...
        "recovery_end_s",24, ...
        "recovery_start_after_gust_end_s", ...
            4-double(def.public_constants.gust_duration_s), ...
        "recovery_definition", ...
            "paired persistent post-gust residual RMS", ...
        "no_gust_schedule_error",noGust.gust_schedule_error, ...
        "gust_schedule_error",gust.gust_schedule_error, ...
        "state_delta",stateDelta, ...
        "air_data_delta",airDelta, ...
        "load_delta",loadDelta, ...
        "actuator_delta",actuatorDelta, ...
        "recovery_delta",recoveryDelta);
end
end

function audit = static_audit(model,def)
required = string({def.outputs.name});
audit = struct( ...
    "required_outputs",required, ...
    "connected_outputs",strings(0,1), ...
    "source_block_types",strings(0,1), ...
    "missing_outputs",strings(0,1), ...
    "duplicate_outputs",strings(0,1), ...
    "output_contract_connected",false, ...
    "precomputed_direct_output_count",0, ...
    "suspicious_callbacks",strings(0,1), ...
    "suspicious_callback_count",0, ...
    "dynamic_block_count",0, ...
    "persistent_chart_count",0, ...
    "dynamic_state_evidence",false);
blocks = find_system(model, ...
    "LookUnderMasks","all","FollowLinks","on","Type","Block");
if ~isempty(blocks)
    types = string(get_param(blocks,"BlockType"));
    dynamicTypes = [ ...
        "Integrator","DiscreteIntegrator","UnitDelay", ...
        "Memory","Delay","StateSpace","TransferFcn", ...
        "DiscreteStateSpace","DiscreteTransferFcn"];
    audit.dynamic_block_count = nnz(ismember(types,dynamicTypes));
end
try
    root = sfroot;
    charts = find(root,"-isa","Stateflow.EMChart");
    for index = 1:numel(charts)
        chartPath = string(charts(index).Path);
        if startsWith(chartPath,model + "/") && ...
                contains(lower(string(charts(index).Script)),"persistent")
            audit.persistent_chart_count = ...
                audit.persistent_chart_count+1;
        end
    end
catch
end
audit.dynamic_state_evidence = ...
    audit.dynamic_block_count > 0 || audit.persistent_chart_count > 0;

callbackNames = [ ...
    "PreLoadFcn","PostLoadFcn","InitFcn","StartFcn","StopFcn"];
% Reading or supplying declared base-workspace inputs is part of the public
% contract and is not, by itself, evidence of a replay shortcut.  Flag
% callbacks only when they reach for an external data source.  The separate
% output-source and causal-dynamics checks remain responsible for detecting
% prescribed/precomputed outputs.
callbackTokens = [ ...
    "load(","load ","matfile","fromworkspace", ...
    "readmatrix(","readtable(","importdata(","fopen("];
for index = 1:numel(callbackNames)
    try
        text = lower(string(get_param(model,callbackNames(index))));
        if strlength(strtrim(text)) > 0 && ...
                any(contains(text,callbackTokens))
            audit.suspicious_callbacks(end+1,1) = ...
                callbackNames(index); %#ok<AGROW>
        end
    catch
    end
end
audit.suspicious_callback_count = numel(audit.suspicious_callbacks);

toWorkspace = find_system(model, ...
    "LookUnderMasks","all","FollowLinks","on", ...
    "BlockType","ToWorkspace");
for outputIndex = 1:numel(required)
    matches = strings(0,1);
    for blockIndex = 1:numel(toWorkspace)
        if string(get_param(toWorkspace{blockIndex},"VariableName")) == ...
                required(outputIndex)
            matches(end+1,1) = string(toWorkspace{blockIndex}); %#ok<AGROW>
        end
    end
    if numel(matches) > 1
        audit.duplicate_outputs(end+1,1) = required(outputIndex);
    end
    connected = false;
    sourceType = "";
    sourceHandle = -1;
    for matchIndex = 1:numel(matches)
        ports = get_param(matches(matchIndex),"PortHandles");
        line = get_param(ports.Inport(1),"Line");
        if line > 0
            sourceHandle = get_param(line,"SrcBlockHandle");
            if sourceHandle > 0
                connected = true;
                sourceType = string(get_param(sourceHandle,"BlockType"));
                break
            end
        end
    end
    if connected
        audit.connected_outputs(end+1,1) = required(outputIndex);
        audit.source_block_types(end+1,1) = sourceType;
        if has_forbidden_upstream(sourceHandle,8)
            audit.precomputed_direct_output_count = ...
                audit.precomputed_direct_output_count+1;
        end
    else
        audit.missing_outputs(end+1,1) = required(outputIndex);
    end
end
audit.output_contract_connected = ...
    numel(audit.connected_outputs) == numel(required) && ...
    isempty(audit.duplicate_outputs);
end

function hit = has_forbidden_upstream(blockHandle,remainingDepth)
hit = false;
if blockHandle <= 0, return; end
blockType = string(get_param(blockHandle,"BlockType"));
forbidden = [ ...
    "Constant","FromWorkspace","SignalBuilder", ...
    "FromFile","Playback","RepeatingSequence", ...
    "Clock","DigitalClock","Inport"];
if ismember(blockType,forbidden)
    hit = true;
    return
end
stopping = [ ...
    "SubSystem","S-Function","MATLABSystem", ...
    "Integrator","DiscreteIntegrator","UnitDelay", ...
    "Memory","Delay","StateSpace","TransferFcn", ...
    "DiscreteStateSpace","DiscreteTransferFcn"];
if remainingDepth <= 0 || ismember(blockType,stopping), return; end
ports = get_param(blockHandle,"PortHandles");
if ~isfield(ports,"Inport"), return; end
for index = 1:numel(ports.Inport)
    line = get_param(ports.Inport(index),"Line");
    if line <= 0, continue; end
    parent = get_param(line,"SrcBlockHandle");
    if parent > 0 && has_forbidden_upstream(parent,remainingDepth-1)
        hit = true;
        return
    end
end
end

function data = normalize_data(value,time,expectedChannels)
raw = double(value.Data);
timeCount = numel(time);
assert(numel(raw) == timeCount*expectedChannels, ...
    "F90_XAERO03_OUTPUT_ELEMENT_COUNT");
dimensions = size(raw);
candidates = find(dimensions == timeCount);
assert(~isempty(candidates), ...
    "F90_XAERO03_OUTPUT_TIME_DIMENSION");
timeDimension = candidates(1);
order = [timeDimension,setdiff(1:ndims(raw),timeDimension,"stable")];
data = reshape(permute(raw,order),timeCount,[]);
assert(size(data,2) == expectedChannels, ...
    "F90_XAERO03_OUTPUT_CHANNEL_COUNT");
end

function derivative = time_derivative(data,time)
derivative = zeros(size(data));
derivative(1,:) = ...
    (data(2,:)-data(1,:))/(time(2)-time(1));
derivative(end,:) = ...
    (data(end,:)-data(end-1,:))/(time(end)-time(end-1));
delta = time(3:end)-time(1:end-2);
derivative(2:end-1,:) = ...
    (data(3:end,:)-data(1:end-2,:))./delta;
end

function dcm = rotation_series(euler)
count = size(euler,1);
dcm = zeros(3,3,count);
for index = 1:count
    phi = euler(index,1);
    theta = euler(index,2);
    psi = euler(index,3);
    cphi = cos(phi); sphi = sin(phi);
    ctheta = cos(theta); stheta = sin(theta);
    cpsi = cos(psi); spsi = sin(psi);
    dcm(:,:,index) = [ ...
        ctheta*cpsi, ...
        sphi*stheta*cpsi-cphi*spsi, ...
        cphi*stheta*cpsi+sphi*spsi; ...
        ctheta*spsi, ...
        sphi*stheta*spsi+cphi*cpsi, ...
        cphi*stheta*spsi-sphi*cpsi; ...
        -stheta,sphi*ctheta,cphi*ctheta];
end
end

function gust = expected_gust(time,values,def)
gust = zeros(numel(time),3);
active = time >= double(values.gust_time) & ...
    time < double(values.gust_time)+ ...
    double(def.public_constants.gust_duration_s);
heading = double(values.gust_heading)*pi/180;
gust(active,1) = double(values.gust_speed)*cos(heading);
gust(active,2) = double(values.gust_speed)*sin(heading);
end

function value = positive_correlation(x,y)
x = double(x(:)); y = double(y(:));
mask = isfinite(x) & isfinite(y);
x = x(mask); y = y(mask);
if numel(x) < 10 || std(x) < 1e-12 || std(y) < 1e-12
    value = 0;
    return
end
matrix = corrcoef(x,y);
value = max(double(matrix(1,2)),0);
end

function value = circular_mean(angle)
value = atan2(mean(sin(angle)),mean(cos(angle)));
end

function value = wrap_angle(value)
value = mod(value+pi,2*pi)-pi;
end

function value = clip(value,lower,upper)
value = min(max(value,lower),upper);
end

function value = local_rms(value)
if isempty(value), value = Inf; return; end
value = sqrt(mean(double(value).^2,"all"));
end

