function values = nominal_values(def)
values = struct;
for index = 1:numel(def.public_inputs)
    values.(def.public_inputs(index).name) = ...
        def.public_inputs(index).nominal;
end
end

function set_base(values)
names = fieldnames(values);
for index = 1:numel(names)
    assignin("base",names{index},values.(names{index}));
end
end

function snapshot = snapshot_base(names)
snapshot = repmat(struct("name","","exists",false,"value",[]), ...
    numel(names),1);
for index = 1:numel(names)
    snapshot(index).name = names(index);
    snapshot(index).exists = evalin("base", ...
        "exist('" + names(index) + "','var')") == 1;
    if snapshot(index).exists
        snapshot(index).value = evalin("base",names(index));
    end
end
end

function restore_base(snapshot)
for index = 1:numel(snapshot)
    name = snapshot(index).name;
    if snapshot(index).exists
        assignin("base",name,snapshot(index).value);
    else
        evalin("base","clear " + name);
    end
end
end

