    runs = repmat(empty_run,1,0);
end
if nargin < 4
    timeseriesArtifact = struct( ...
        "path","", ...
        "file_presence","", ...
        "format","", ...
        "variable","", ...
        "contains","");
end
if isfield(receipt,"scenario_rows")
    rows = receipt.scenario_rows;
else
    rows = struct([]);
end
if isfield(receipt,"metric_values")
    metrics = receipt.metric_values;
else
    metrics = struct;
end
if isfield(receipt,"static_audit")
    audit = receipt.static_audit;
else
    audit = struct;
end
evidence = struct( ...
    "schema","simuverity.f90-xaero03-evidence.v1", ...
    "formal_id",def.formal_id, ...
    "design_revision",def.design_revision, ...
    "model_path",receipt.model_path, ...
    "model_file_presence",receipt.model_file_presence, ...
    "load_pass",logical(receipt.load_pass), ...
    "update_pass",logical(receipt.update_pass), ...
    "compile_pass",logical(receipt.compile_pass), ...
    "scenario_inputs",scenario_input_identity(runs), ...
    "scenario_rows",rows, ...
    "metric_values",metrics, ...
    "static_audit",audit, ...
    "timeseries_artifact",timeseriesArtifact, ...
    "extraction_only",true, ...
    "contains_score_or_threshold_decisions",false, ...
    "extracted_at",timestamp, ...
    "runtime_identity",runtime_identity);
end

